'use client';

import * as React from 'react';

// @interlace/toolbar v1.0.0 — Interlace design system.
// Docs, props and live preview: https://ds.interlace.tools/c/toolbar
// What changed since: https://ds.interlace.tools/c/toolbar#history
// Generated banner — keep it, the upgrade diff reads this version.

// Built on Base UI's Toolbar. shadcn has no toolbar; the part names follow
// Base UI's (Toolbar, ToolbarButton, ToolbarLink, ToolbarGroup,
// ToolbarSeparator, ToolbarInput).
// Upstream: https://base-ui.com/react/components/toolbar

/**
 * @interlace/ui — Toolbar
 *
 * A row of controls that acts as ONE stop in the Tab order: Tab enters the
 * toolbar on its last-focused control and leaves it on the next Tab, and the
 * arrow keys move between the controls inside, Home and End jump to the ends,
 * and focus wraps. A formatting bar, a table's bulk actions, a player's
 * transport. Without it, a ten-button bar costs a keyboard user ten Tabs to
 * get past.
 *
 * Base UI owns the roving focus (the arrows; this file adds Home and End),
 * the orientation, and keeping a disabled
 * button focusable (so it can still be found and its tooltip read). We own
 * the surface, and the buttons take Button's own variants and sizes, so a
 * toolbar button is a Button that knows it lives in a toolbar.
 *
 * Any Base UI trigger joins the roving focus through `render`:
 * `<ToolbarButton render={<Toggle />} />`, `<ToolbarButton render={<MenuTrigger />} />`,
 * and a Tooltip wraps the other way round,
 * `<TooltipTrigger render={<ToolbarButton />} />`.
 *
 * ## Anatomy
 *
 *   Toolbar                          (Toolbar.Root — div role="toolbar", data-orientation)
 *     ├─ ToolbarButton               (Toolbar.Button — buttonVariants, ghost / icon-sm by default)
 *     ├─ ToolbarLink                 (Toolbar.Link — an anchor in the same roving order)
 *     ├─ ToolbarSeparator            (Toolbar.Separator — perpendicular to the toolbar)
 *     ├─ ToolbarGroup                (Toolbar.Group — role="group", name it with aria-label)
 *     └─ ToolbarInput                (Toolbar.Input — at most one, and last, in a horizontal bar)
 *
 * The one input goes last because Left and Right move the caret inside it,
 * so they cannot also move between controls; Base UI only lets the arrows out
 * at the ends of the text.
 *
 * ## MIN_VIEWPORT — 320
 *
 * The root wraps (`flex-wrap`), so a long bar breaks onto a second row at the
 * 320 floor instead of overflowing. Roving order follows the DOM, not the
 * rows, which is what a reader of the source order expects.
 *
 * | Rule | Concept                          | Where in this file                                          |
 * | ---- | -------------------------------- | ----------------------------------------------------------- |
 * | R4   | Extends Base UI part props       | `React.ComponentProps<typeof BaseToolbar.*>`                |
 * | R6   | data-slot per part               | toolbar / -button / -link / -group / -separator / -input    |
 * | R7   | cn + ...rest                     | `cn(…, className)` + `{...props}`                           |
 * | R8   | Enums, no booleans               | `orientation`; Button's `variant` and `size`                |
 * | R12  | Reuse over wrap                  | Base UI owns roving focus; Button owns the button look      |
 * | R14  | Declares min viewport            | `data-min-viewport` + exported const                        |
 * | R19  | Tokens only                      | `bg-border`, `border-input`, `ring-ring/60`; the link inherits its colour |
 * | R25  | Client component                 | Required — Base UI Toolbar ships client hooks               |
 * | R26  | Keyboard contract                | arrows, Home / End, one Tab stop: asserted by `Toolbar.stories.tsx`, locked by `overlay-nav-keyboard-lock` |
 */

import { Toolbar as BaseToolbar } from '@base-ui/react/toolbar';
import type { VariantProps } from 'class-variance-authority';

import { cn } from '@/lib/utils';
import { buttonVariants } from '@/components/ui/button-variants';

/**
 * Minimum viable viewport (CSS px) — DESIGN_PRINCIPLES #14. The root wraps,
 * so nothing overflows at the 320 floor.
 */
export const MIN_VIEWPORT = 320 as const;

/**
 * Home and End: the WAI-ARIA toolbar pattern's jump to the first and last
 * control. Base UI's toolbar roves with the arrows only, so the root adds the
 * two keys over the same items, the ones Base UI gave a `tabindex`. Inside the
 * input they stay with the caret.
 */
function jumpToEnd(event: React.KeyboardEvent<HTMLDivElement>) {
  if (event.key !== 'Home' && event.key !== 'End') return;
  if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
  if (event.target instanceof HTMLInputElement) return;
  const items = Array.from(
    event.currentTarget.querySelectorAll<HTMLElement>(':is(button, a, input)[tabindex]'),
  );
  const target = event.key === 'Home' ? items[0] : items[items.length - 1];
  if (!target) return;
  event.preventDefault();
  target.focus();
}

function Toolbar({
  className,
  onKeyDown,
  ...props
}: React.ComponentProps<typeof BaseToolbar.Root>) {
  return (
    <BaseToolbar.Root
      data-slot="toolbar"
      data-min-viewport={String(MIN_VIEWPORT)}
      onKeyDown={(event) => {
        // A disabled-but-focusable button already prevented every key but
        // Tab, so only a prevent added by the caller's handler opts out.
        const prevented = event.defaultPrevented;
        onKeyDown?.(event);
        if (event.defaultPrevented && !prevented) return;
        jumpToEnd(event);
      }}
      className={cn(
        'group/toolbar flex flex-wrap items-center gap-1',
        'data-[orientation=vertical]:flex-col data-[orientation=vertical]:flex-nowrap data-[orientation=vertical]:items-stretch',
        className,
      )}
      {...props}
    />
  );
}

type ToolbarButtonProps = React.ComponentProps<typeof BaseToolbar.Button> &
  VariantProps<typeof buttonVariants>;

function ToolbarButton({ className, variant = 'ghost', size = 'icon-sm', ...props }: ToolbarButtonProps) {
  return (
    <BaseToolbar.Button
      data-slot="toolbar-button"
      // A disabled toolbar button stays focusable (Base UI's default), so it
      // dims without `pointer-events-none`: hovering it can still show why.
      className={cn(
        buttonVariants({ variant, size }),
        // An icon button is a square with no padding. Said outright so a
        // rendered Toggle's own `px-*` cannot squeeze the icon.
        size?.startsWith('icon') && 'p-0',
        'data-[disabled]:pointer-events-auto data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50',
        className,
      )}
      {...props}
    />
  );
}

function ToolbarLink({ className, ...props }: React.ComponentProps<typeof BaseToolbar.Link>) {
  return (
    <BaseToolbar.Link
      data-slot="toolbar-link"
      className={cn(
        // Inherits its colour and is underlined at rest, like Button's
        // `link` variant: a toolbar sits on surfaces the DS does not paint.
        'rounded-md px-2 py-1 text-sm underline decoration-from-font underline-offset-4 outline-none hover:decoration-2',
        'focus-visible:ring-ring/60 focus-visible:ring-[3px]',
        className,
      )}
      {...props}
    />
  );
}

function ToolbarGroup({ className, ...props }: React.ComponentProps<typeof BaseToolbar.Group>) {
  return (
    <BaseToolbar.Group
      data-slot="toolbar-group"
      className={cn(
        'flex items-center gap-1',
        'group-data-[orientation=vertical]/toolbar:flex-col',
        className,
      )}
      {...props}
    />
  );
}

function ToolbarSeparator({
  className,
  ...props
}: React.ComponentProps<typeof BaseToolbar.Separator>) {
  return (
    <BaseToolbar.Separator
      data-slot="toolbar-separator"
      // Base UI sets the separator's OWN orientation, perpendicular to the
      // toolbar's: a horizontal bar gets a vertical rule.
      className={cn(
        'bg-border shrink-0',
        'data-[orientation=vertical]:mx-1 data-[orientation=vertical]:h-5 data-[orientation=vertical]:w-px',
        'data-[orientation=horizontal]:my-1 data-[orientation=horizontal]:h-px data-[orientation=horizontal]:w-full',
        className,
      )}
      {...props}
    />
  );
}

function ToolbarInput({ className, ...props }: React.ComponentProps<typeof BaseToolbar.Input>) {
  return (
    <BaseToolbar.Input
      data-slot="toolbar-input"
      className={cn(
        'border-input bg-background text-foreground placeholder:text-muted-foreground h-8 min-w-0 rounded-lg border px-2.5 text-sm shadow-xs outline-none',
        'focus-visible:border-ring focus-visible:ring-ring/60 focus-visible:ring-[3px]',
        'disabled:cursor-not-allowed disabled:opacity-50',
        className,
      )}
      {...props}
    />
  );
}

export { Toolbar, ToolbarButton, ToolbarLink, ToolbarGroup, ToolbarSeparator, ToolbarInput };
export type { ToolbarButtonProps };

import { cva, type VariantProps } from 'class-variance-authority';

/**
 * @interlace/ui — buttonVariants
 *
 * The cva variant map that `button.tsx` imports — variant × size class strings
 * and nothing else. Pure CVA: no React, no client APIs, so a server component
 * can style a plain `<a>` with `buttonVariants({ variant, size })`.
 *
 * This is not a component. It exports a function and a type, renders nothing,
 * and has no props, no slots and no DOM — which is exactly why it is a
 * separate module from the `'use client'` Button that consumes it.
 *
 * ## Anatomy
 *
 *   buttonVariants({ variant, size })
 *     ├─ variant  default | highlight | destructive | outline | secondary | ghost | link
 *     └─ size     default | xs | sm | lg | icon | icon-xs | icon-sm | icon-lg
 *
 * Defaults are `variant: 'default'`, `size: 'default'`. `pagination.tsx` is
 * the in-repo example of styling an element rather than nesting a Button: its
 * `<a>` takes `buttonVariants({ variant, size })` directly. (It reaches the
 * function through `button.js`, which re-exports it — that path is
 * `'use client'`; import from this module to keep a server tree server-side.)
 *
 * ## Why half this file is comments
 *
 * Four of the seven variants carry a long note recording a measured contrast
 * failure and the rule it produced: a variant that declares its own foreground
 * must paint an opaque surface in the same state, because a button is dropped
 * onto surfaces the design system does not control. `outline` inheriting the
 * page text into a `bg-primary` section measured 1.05:1; `link` with
 * `text-primary` on the same section measured 1.00:1. `composite-contrast-lock`
 * composites every variant over every brandable backdrop, so those notes are
 * checkable rather than folklore.
 *
 * | Rule | Concept                          | Where in this file                                          |
 * | ---- | -------------------------------- | ----------------------------------------------------------- |
 * | R8   | Enums, no booleans               | `variant` and `size` are closed string enums                |
 * | R19  | Tokens only                      | `bg-primary`, `bg-destructive`, `bg-accent`, `ring-ring/50` |
 * | R20  | AA contrast                      | every pair composited by `composite-contrast-lock`          |
 * | R25  | Server-safe                      | no React import, no hooks, no `'use client'`                |
 */

// Server-safe button variants. The full `<Button>` component lives in
// `./button.tsx` and is `'use client'` (Base UI useRender). Variants are a
// pure CVA function — no React, no client APIs — so they can be called
// from server components when composing className strings (e.g. on a
// `<Link className={buttonVariants(...)}>` in a server-rendered page).

const buttonVariants = cva(
  "relative isolate inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-lg text-sm font-medium transition-[color,background-color,border-color,box-shadow,scale] duration-(--duration-fast) ease-enter motion-safe:active:scale-[0.97] disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg:not([class*='size-'])]:size-4 shrink-0 [&_svg]:shrink-0 outline-none focus-visible:border-ring focus-visible:ring-ring/50 focus-visible:ring-[3px] aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive",
  {
    variants: {
      variant: {
        default: 'bg-primary text-primary-foreground hover:bg-primary/90',
        // The warm call-to-action that is NOT the brand primary: the second
        // button on a hero, "start here" beside a primary "sign up". Opaque
        // face plus its own foreground, so it holds on any section surface.
        highlight:
          'bg-highlight text-highlight-foreground hover:bg-highlight/90',
        // No `dark:bg-destructive/60` here, unlike stock shadcn — see the
        // matching note in badge.tsx. Our dark destructive token is a light
        // red tuned for AAA on near-black; muting it to 60% drops the label
        // to 4.27:1, under AA. Caught by composite-contrast-lock.
        destructive:
          'bg-destructive text-destructive-foreground hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:focus-visible:ring-destructive/40',
        // `text-foreground` is NOT redundant, and neither is the ABSENCE of
        // stock shadcn's `dark:bg-input/30` / `dark:hover:bg-input/50`. Both
        // halves of that come from the same shipped defect, found twice.
        //
        // First half: `outline` paints an opaque surface (`bg-background`)
        // but was the only such variant that did not also set a foreground,
        // so it INHERITED one. Dropped inside a section that flips the text
        // colour — `<CTASection tone="primary">` is `bg-primary
        // text-primary-foreground` — the button kept the page background and
        // took the section's white text: 1.05:1, invisible.
        //
        // Second half: declaring a foreground only means something if the
        // surface under it is actually opaque. `dark:bg-input/30` overrode
        // `bg-background` with a 30% tint, so in dark mode the same
        // `bg-primary` section bled through — `#6b635a` at 30% over `#fbb99a`
        // composites to `#d09f87`, and `text-foreground` `#f0ede9` lands on
        // that at 2.00:1. The hover state was worse-shaped and identical in
        // result (`dark:hover:bg-input/50` + `hover:text-accent-foreground`,
        // 2.00:1). Dropping both makes dark match what light already did:
        // no fill, the control identified by its border — `dark:border-input`
        // is 3.35:1 on the dark background, clearing SC 1.4.11.
        //
        // The rule, stated so it is checkable: a variant that declares its own
        // foreground must paint an opaque surface in the same state, because
        // a button is dropped onto surfaces the DS does not control. Locked by
        // composite-contrast-lock, which composites every variant over every
        // brandable backdrop rather than over the page background.
        outline:
          'border bg-background text-foreground shadow-xs hover:bg-accent hover:text-accent-foreground dark:border-input',
        secondary:
          'bg-secondary text-secondary-foreground hover:bg-secondary/80',
        // No `dark:hover:bg-accent/50` here, for the reason spelled out on
        // `outline`: it declares `hover:text-accent-foreground`, so a 50% hover
        // surface let a `bg-primary` section through at 3.07:1. Opaque
        // `bg-accent` carries its own foreground at 10.46:1 in both schemes.
        // At rest `ghost` declares neither colour and inherits both, which is
        // the variant's whole point and is safe anywhere.
        ghost: 'hover:bg-accent hover:text-accent-foreground',
        // Inherits its colour, and is underlined at rest rather than only on
        // hover. Stock shadcn is `text-primary … hover:underline`, which is
        // the same defect as the two above in its purest form: a declared
        // foreground over a surface the variant does not paint. `text-primary`
        // on a `<CTASection tone="primary">` is `#7d350c` on `#7d350c` —
        // 1.00:1, the button is literally the same colour as the section.
        //
        // A variant with no surface of its own cannot name a colour; the only
        // safe foreground is the inherited one, which is by construction the
        // pair its surface was measured with. That leaves the underline to
        // carry the affordance, so it has to be there at rest — which also
        // retires a colour-only link cue (WCAG 1.4.1) and matches how `Prose`
        // already renders links. `decoration-from-font` is Prose's too; hover
        // thickens the rule instead of shifting the hue, because any hue we
        // could shift to reintroduces the bug.
        // A link does not press like a button: it keeps its size.
        link: 'underline underline-offset-4 decoration-from-font hover:decoration-2 motion-safe:active:scale-100',
      },
      size: {
        default: 'h-9 px-4 py-2 has-[>svg]:px-3',
        xs: "h-6 gap-1 rounded-lg px-2 text-xs has-[>svg]:px-1.5 [&_svg:not([class*='size-'])]:size-3",
        sm: 'h-8 rounded-lg gap-1.5 px-3 has-[>svg]:px-2.5',
        lg: 'h-10 rounded-lg px-6 has-[>svg]:px-4',
        icon: 'size-9',
        'icon-xs': "size-6 rounded-lg [&_svg:not([class*='size-'])]:size-3",
        'icon-sm': 'size-8',
        'icon-lg': 'size-10',
      },
    },
    defaultVariants: {
      variant: 'default',
      size: 'default',
    },
  },
);

export { buttonVariants };
export type { VariantProps };
